}

disk_id=$(getarg clearme_disk_id || true)
root_uuid=$(getarg clearme_root_partuuid || true)
fallback=$(getarg clearme_disk || true)
keep=$(getarg clearme_keep || true)

normalize_id() {
    tr 'A-F' 'a-f' | tr -d '{}' | sed 's/^0x//'
}

# Generated by clearme.
