    fi
    if command -v fdisk >/dev/null 2>&1; then
        id=$(fdisk -l "$dev" 2>/dev/null | grep -i 'disk identifier' | tail -n 1 |
            sed 's/.*: *//' | normalize_id)
        if [ -n "$id" ]; then
            printf '%s\n' "$id"
            return 0
